using System.Globalization;
using System.Reflection;
using System.Text.Json;

namespace SAM.App.Localization;

/// <summary>
/// UI texts from the embedded files SAM.App/Strings/*.json.
/// The property or method for each text is generated by tools/strings.py (Strings.g.cs).
/// </summary>
public static partial class Strings
{
    private static Dictionary<string, string> _texts = [];
    private static Dictionary<string, string> _fallback = [];

    /// <summary>Id of the loaded translation, e.g. "de-CH" or "zh-Hant".</summary>
    public static string TranslationId { get; private set; } = "en";

    public static void Load(string translationId)
    {
        _fallback = Read("en") ?? [];
        var texts = translationId == "en" ? _fallback : Read(translationId);
        _texts = texts ?? _fallback;
        TranslationId = texts is null ? "en" : translationId;
    }

    public static bool Exists(string translationId)
        => Assembly.GetExecutingAssembly().GetManifestResourceInfo(ResourceName(translationId)) is not null;

    private static string Get(string key)
        => _texts.TryGetValue(key, out var text) || _fallback.TryGetValue(key, out text) ? text : key;

    private static string Format(string key, params object[] args)
        => string.Format(CultureInfo.CurrentCulture, Get(key), args);

    private static string ResourceName(string translationId) => "SAM.App.Strings." + translationId + ".json";

    private static Dictionary<string, string>? Read(string translationId)
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(ResourceName(translationId));

        if (stream is null)
        {
            return null;
        }

        using var document = JsonDocument.Parse(stream);
        var result = new Dictionary<string, string>(StringComparer.Ordinal);

        foreach (var property in document.RootElement.EnumerateObject())
        {
            if (property.Value.ValueKind == JsonValueKind.String)
            {
                result[property.Name] = property.Value.GetString()!;
            }
        }

        return result;
    }
}
